css:
@font-face {
  font-family: "Arimo";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("{{font:arimo-400-700-cyrillic.woff2}}") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Arimo";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("{{font:arimo-400-700-latin.woff2}}") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
/* Desktop skins only. Default and mobile keep their original palette/layout. */
:root[data-platform="desktop"][data-style-family="glass"] {
  --wecid-app-bg: #e8f4fb;
  --wecid-surface: #f6fbff;
  --wecid-surface-hover: #e2f0fc;
  --wecid-text: #142b4d;
  --wecid-text-secondary: #36536d;
  --wecid-text-muted: #49647d;
  --wecid-border: #b1cfe4;
  --wecid-control-border: #aac8de;
  --wecid-border-strong: #6a9fc8;
  --wecid-card-bg: #fcfeff;
  --wecid-column-bg: #e3f3ff;
  --wecid-board-bg: #c6e5f4;
  --wecid-soft-bg: #dfeefa;
  --wecid-soft-bg-hover: #d0e6f7;
  --wecid-focus-ring: #1572b829;
  --wecid-shadow: #17486618;
  --wecid-danger: #b51c34;
  --wecid-style-accent: #0866ae;
  --wecid-style-accent-dark: #064d86;
  --wecid-style-accent-pale: #e0f1ff;
  --wecid-style-top: #b3ddff;
  --wecid-style-button: linear-gradient(#62b6f5 0%, #2793e5 48%, #0871c9 49%, #0865b4 100%);
  color-scheme: light;
}
:root[data-platform="desktop"][data-desktop-style="frutiger"] {
  --wecid-app-bg: #ebfaf4;
  --wecid-surface: #f6fffb;
  --wecid-surface-hover: #ddf5eb;
  --wecid-text: #173c38;
  --wecid-text-secondary: #315b54;
  --wecid-text-muted: #416961;
  --wecid-border: #afd4c8;
  --wecid-control-border: #a2cdbc;
  --wecid-border-strong: #5b9a82;
  --wecid-column-bg: #e1f9ef;
  --wecid-board-bg: #caecdf;
  --wecid-soft-bg: #e1f5ec;
  --wecid-soft-bg-hover: #caeede;
  --wecid-style-accent: #087e50;
  --wecid-style-accent-dark: #065c3b;
  --wecid-style-accent-pale: #dcf6e9;
  --wecid-style-top: #b7efdf;
  --wecid-style-button: linear-gradient(#56c690 0%, #24a36b 48%, #078050 49%, #087446 100%);
}
:root[data-platform="desktop"][data-style-family="glass"] .app-header {
  border-bottom: 1px solid var(--wecid-control-border);
  background: linear-gradient(110deg, #ffffffee, #edfaffcc 46%, #ffffffea);
  box-shadow: inset 0 1px #fff;
}
:root[data-platform="desktop"][data-style-family="glass"] .app-title { letter-spacing: .02em; text-shadow: 0 1px #fff; }
:root[data-platform="desktop"][data-style-family="glass"] .settings-button { background: linear-gradient(#fff, var(--wecid-style-accent-pale)); box-shadow: inset 0 1px #fff, 0 1px 2px var(--wecid-shadow); }
:root[data-platform="desktop"][data-desktop-style="terminal"] {
  font-family: "PT Mono", Consolas, monospace;
  --wecid-app-bg: #0d151a;
  --wecid-surface: #142027;
  --wecid-surface-hover: #1d3038;
  --wecid-text: #e4edeb;
  --wecid-text-secondary: #b3c4c9;
  --wecid-text-muted: #9bb0b6;
  --wecid-border: #354a53;
  --wecid-control-border: #50636b;
  --wecid-border-strong: #edb746;
  --wecid-card-bg: #142128;
  --wecid-column-bg: #101c22;
  --wecid-board-bg: #0b1419;
  --wecid-soft-bg: #24343b;
  --wecid-soft-bg-hover: #32434a;
  --wecid-focus-ring: #edb7463d;
  --wecid-shadow: #00000050;
  --wecid-danger: #ffa39d;
  --wecid-style-accent: #edb746;
  --wecid-style-accent-dark: #facd71;
  --wecid-style-accent-pale: #332c1b;
  --wecid-style-button: linear-gradient(#304047, #1e2c33 48%, #16242b);
  --wecid-press-highlight: #82969f60;
  --wecid-press-shadow: #000000a0;
  --wecid-press-fill: #0a1217;
  color-scheme: dark;
}
:root[data-platform="desktop"][data-style-family="terminal"] .app-title { color: var(--wecid-style-accent); letter-spacing: .06em; font-weight: 400; }
:root[data-platform="desktop"][data-style-family="terminal"] .app-header { border-color: var(--wecid-control-border); background: var(--wecid-app-bg); }

/* XP-like raised edges and an immediate sunken press. Paint/translate only:
 * no timers, layout shifts, sound, or changes to sortable handles. */
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"])
  :where(button:not([aria-roledescription="sortable"]):not([role="switch"]), select) {
  border-radius: 4px;
  box-shadow: inset 1px 1px 0 var(--wecid-press-highlight), inset -1px -1px 0 var(--wecid-press-shadow), 0 1px 2px var(--wecid-shadow);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"])
  :where(button:not([aria-roledescription="sortable"]):not([role="switch"])):active:not(:disabled):not([aria-disabled="true"]) {
  translate: 1px 1px;
  box-shadow: inset 1px 1px 2px var(--wecid-press-shadow), inset -1px -1px 0 var(--wecid-press-highlight);
  background-image: none;
  background-color: var(--wecid-press-fill);
  color: var(--wecid-text);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) :where(button, select, input, textarea):focus-visible {
  outline: 1px dashed var(--wecid-style-accent);
  outline-offset: 3px;
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) :where(select, input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]), textarea) {
  border-radius: 4px;
  border-color: var(--wecid-control-border);
  color: var(--wecid-text);
  box-shadow: inset 1px 1px 2px var(--wecid-shadow);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) select {
  background-color: var(--wecid-surface);
  accent-color: var(--wecid-style-accent);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) option { background: var(--wecid-surface); color: var(--wecid-text); }

/* Aero skins change paint only: preserve board scrolling, DnD geometry and
 * explicit user colours. No opacity on card ancestors or live backdrop blur. */
:root[data-platform="desktop"][data-style-family="glass"] .{{board.boardToolbar}} {
  background: linear-gradient(#f8fdfff5, #e5f4ffe8); border-color: var(--wecid-control-border);
  box-shadow: inset 0 1px #fff; gap: 8px;
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.column}} {
  border-color: var(--wecid-control-border); border-radius: 10px;
  box-shadow: 0 3px 12px #14456716, inset 0 1px #fff;
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.columnBody}} {
  background: color-mix(in srgb, var(--wecid-column-bg) var(--wecid-column-fill, 100%), transparent);
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.columnHeader}}:not([data-colored="true"]) {
  background: linear-gradient(#ffffffbb, transparent), color-mix(in srgb, var(--wecid-style-top) var(--wecid-column-fill, 100%), transparent);
  border-bottom-color: var(--wecid-control-border); text-shadow: 0 1px #ffffffaa;
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.taskCard}}:not([data-colored="true"]) {
  background: linear-gradient(#fff, var(--wecid-card-bg)); border-color: var(--wecid-border);
  box-shadow: 0 2px 5px #1748660d, inset 0 1px #fff;
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.addColumnButton}},
:root[data-platform="desktop"][data-style-family="glass"] .{{board.planningFilterButtonActive}},
:root[data-platform="desktop"][data-style-family="glass"] .{{board.createButton}},
:root[data-platform="desktop"][data-style-family="glass"] .{{board.createTaskButton}} {
  background: var(--wecid-style-button); color: #fff; border: 1px solid var(--wecid-style-accent-dark);
  box-shadow: inset 0 1px #ffffffa3, 0 1px 2px var(--wecid-shadow); text-shadow: 0 1px #0003;
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.planningFilterButton}}:not(.{{board.planningFilterButtonActive}}),
:root[data-platform="desktop"][data-style-family="glass"] .{{board.priorityFilterSelect}},
:root[data-platform="desktop"][data-style-family="glass"] .{{board.tagFilterSelect}} {
  background: linear-gradient(#fff, var(--wecid-style-accent-pale));
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.addTaskButton}} {
  margin: 10px 0 0; min-height: 36px; border: 1px solid var(--wecid-border); border-radius: 7px;
  background: linear-gradient(#ffffffb3, #ffffff40); color: var(--wecid-style-accent-dark);
}
:root[data-platform="desktop"][data-style-family="glass"] .{{board.addTaskButton}}:hover { background: var(--wecid-surface); }
:root[data-platform="desktop"][data-style-family="glass"] .{{board.taskDropPlaceholder}} {
  border-color: var(--wecid-style-accent); background: color-mix(in srgb, var(--wecid-style-accent) 12%, transparent);
}

/* XP/terminal skins preserve sortable geometry and the user's solid/media
 * background. Decorations are static CSS and never intercept a pointer. */
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.boardToolbar}} {
  background: var(--wecid-surface);
  box-shadow: inset 0 1px var(--wecid-press-highlight), 0 2px 4px var(--wecid-shadow);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.column}} { border-radius: 5px; }
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.columnHeader}}:not([data-colored="true"]) {
  background: color-mix(in srgb, var(--wecid-column-bg) var(--wecid-column-fill, 100%), transparent);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.addColumnButton}},
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.planningFilterButtonActive}},
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.createButton}},
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.createTaskButton}} {
  background: var(--wecid-style-button);
  border: 1px solid var(--wecid-style-accent);
  color: var(--wecid-surface);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.planningFilterButton}}:not(.{{board.planningFilterButtonActive}}) { background: var(--wecid-surface); }
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.addTaskButton}} {
  border: 1px dashed var(--wecid-control-border);
  background: var(--wecid-surface);
  color: var(--wecid-style-accent-dark);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.actionMenu}} {
  border: 1px solid var(--wecid-control-border);
  border-radius: 3px;
  padding: 3px;
  box-shadow: inset 1px 1px var(--wecid-press-highlight), inset -1px -1px var(--wecid-press-shadow), 3px 3px 0 var(--wecid-shadow);
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.actionMenuItem}} {
  border-radius: 1px;
  box-shadow: none;
  translate: none;
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.actionMenuItem}}:not(.{{board.actionMenuItemDanger}}):is(:hover, :focus-visible) {
  background: var(--wecid-style-accent);
  color: var(--wecid-app-bg);
  outline-offset: -3px;
}
:root[data-platform="desktop"]:is([data-style-family="xp"], [data-style-family="terminal"]) .{{board.taskDropPlaceholder}} {
  border-color: var(--wecid-style-accent);
  background: color-mix(in srgb, var(--wecid-style-accent) 12%, transparent);
  border-radius: 4px;
}

:root[data-platform="desktop"][data-style-family="terminal"] .{{board.column}} { border-radius: 3px; box-shadow: none; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.columnTitle}} { color: inherit; font-weight: 400; letter-spacing: .02em; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.columnHeader}}:not([data-colored="true"]) { color: var(--wecid-style-accent); }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}} { border-radius: 2px; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) {
  background: var(--wecid-card-bg);
  border-color: var(--wecid-control-border);
  box-shadow: inset 0 1px #ffffff05;
}
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskMetadataBadge}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskTagBadge}} { border-radius: 2px; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskMetadataBadge}} {
  border: 1px solid currentColor;
  background: #101b21;
  color: #bed0d6;
  box-shadow: none;
}
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskPriorityMedium}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskDue}} { color: #edbd60; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskPriorityHigh}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskDueOverdue}} { color: #ffaaa1; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskReminder}} { color: #d0b3f4; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskChecklistBadge}} { color: #9bdfb1; background: #122a23; border-radius: 2px; border: 1px solid #58856a; }
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.taskCard}}:not([data-colored="true"]) .{{board.taskTagBadge}} {
  background: #1c2b32;
  color: #bdcfd2;
  border: 1px solid #50636b;
}
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.addColumnButton}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.planningFilterButtonActive}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.createButton}},
:root[data-platform="desktop"][data-style-family="terminal"] .{{board.createTaskButton}} { color: var(--wecid-style-accent); }

:root[data-platform="desktop"][data-style-family="glass"] .{{updates.newsButton}} { background: linear-gradient(#fff, var(--wecid-style-accent-pale)); box-shadow: inset 0 1px #fff; }

/* Classic XP appearance based on the approved light and dark mockups.
 * Tahoma is used when installed; Arimo is the bundled Cyrillic fallback. */
:root[data-platform="desktop"][data-style-family="xp"] {
  font-family: Tahoma, "Arimo", Arial, sans-serif;
  --wecid-app-bg: #c3c4c7;
  --wecid-surface: #d0d0d0;
  --wecid-surface-hover: #dfdfdf;
  --wecid-text: #161820;
  --wecid-text-secondary: #30343b;
  --wecid-text-muted: #50535b;
  --wecid-border: #808080;
  --wecid-control-border: #777;
  --wecid-border-strong: #000080;
  --wecid-card-bg: #fff;
  --wecid-column-bg: #c5c5c5;
  --wecid-board-bg: #c3c4c7;
  --wecid-soft-bg: #e4e4e4;
  --wecid-soft-bg-hover: #dadada;
  --wecid-focus-ring: #00008033;
  --wecid-shadow: #00000035;
  --wecid-danger: #a32121;
  --wecid-style-accent: #00009c;
  --wecid-style-accent-dark: #000080;
  --wecid-style-accent-pale: #d4dcfa;
  --wecid-style-button: linear-gradient(#0000ca, #00009c);
  --wecid-press-highlight: #fff;
  --wecid-press-shadow: #555;
  --wecid-press-fill: #b6b6b6;
  --wecid-xp-heading: #00009c;
  --wecid-xp-heading-text: #fff;
  --wecid-xp-list: #fff;
  --wecid-xp-edge-light: #f8f8f8;
  --wecid-xp-edge-dark: #505050;
  color-scheme: light;
}
:root[data-platform="desktop"][data-desktop-style="xp-dark"] {
  --wecid-app-bg: #23262b;
  --wecid-surface: #3b3f47;
  --wecid-surface-hover: #484e58;
  --wecid-text: #f1f2f5;
  --wecid-text-secondary: #d7dce4;
  --wecid-text-muted: #bbc1cd;
  --wecid-border: #737b87;
  --wecid-control-border: #78808c;
  --wecid-border-strong: #8b9fd8;
  --wecid-card-bg: #252a32;
  --wecid-column-bg: #383e46;
  --wecid-board-bg: #202328;
  --wecid-soft-bg: #424954;
  --wecid-soft-bg-hover: #505968;
  --wecid-focus-ring: #8099ea55;
  --wecid-shadow: #00000070;
  --wecid-danger: #ffaaa3;
  --wecid-style-accent: #899fed;
  --wecid-style-accent-dark: #adbcff;
  --wecid-style-accent-pale: #283252;
  --wecid-style-button: linear-gradient(#0000c8, #000080);
  --wecid-press-highlight: #a1a9b3;
  --wecid-press-shadow: #0b0d10;
  --wecid-press-fill: #22262e;
  --wecid-xp-list: #171b21;
  --wecid-xp-edge-light: #9da3ad;
  --wecid-xp-edge-dark: #080a0d;
  color-scheme: dark;
}
:root[data-platform="desktop"][data-style-family="xp"] .app-header {
  background: linear-gradient(110deg, var(--wecid-surface), var(--wecid-app-bg));
  border-bottom: 2px solid var(--wecid-xp-edge-dark);
  box-shadow: inset 1px 1px var(--wecid-xp-edge-light);
}
:root[data-platform="desktop"][data-style-family="xp"] .app-title {
  font-family: "Lucida Console", "Courier New", monospace;
  font-size: 28px;
  letter-spacing: -.035em;
  color: var(--wecid-style-accent);
  text-shadow: 1px 1px var(--wecid-press-highlight);
}
:root[data-platform="desktop"][data-style-family="xp"] :where(button:not([aria-roledescription="sortable"]):not([role="switch"]), select) {
  transition: none;
  border: 2px solid;
  border-color: var(--wecid-xp-edge-light) var(--wecid-xp-edge-dark) var(--wecid-xp-edge-dark) var(--wecid-xp-edge-light);
  border-radius: 0;
  box-shadow: inset -1px -1px var(--wecid-border), inset 1px 1px var(--wecid-press-highlight);
}
:root[data-platform="desktop"][data-style-family="xp"] :where(button:not([aria-roledescription="sortable"]):not([role="switch"])):active:not(:disabled):not([aria-disabled="true"]) {
  border-color: var(--wecid-xp-edge-dark) var(--wecid-xp-edge-light) var(--wecid-xp-edge-light) var(--wecid-xp-edge-dark);
  box-shadow: inset 1px 1px var(--wecid-border);
}
:root[data-platform="desktop"][data-style-family="xp"] :where(button, select, input, textarea):focus-visible {
  outline: 1px dotted currentColor;
  outline-offset: -5px;
}
:root[data-platform="desktop"][data-style-family="xp"] :where(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]), textarea, select) {
  border-radius: 0;
  border: 2px solid;
  border-color: var(--wecid-xp-edge-dark) var(--wecid-xp-edge-light) var(--wecid-xp-edge-light) var(--wecid-xp-edge-dark);
  background-color: var(--wecid-xp-list);
  box-shadow: inset 1px 1px var(--wecid-border);
  color: var(--wecid-text);
}
:root[data-platform="desktop"][data-style-family="xp"] .{{board.boardToolbar}} {
  border-bottom: 2px solid var(--wecid-xp-edge-dark);
  box-shadow: inset 0 1px var(--wecid-xp-edge-light);
}
:root[data-platform="desktop"][data-style-family="xp"] .{{board.column}} {
  height: 100%;
  border: 2px solid;
  border-color: var(--wecid-xp-edge-light) var(--wecid-xp-edge-dark) var(--wecid-xp-edge-dark) var(--wecid-xp-edge-light);
  padding: 4px;
  border-radius: 0;
  box-shadow: inset -1px -1px var(--wecid-border), inset 1px 1px var(--wecid-press-highlight);
}
:root[data-platform="desktop"][data-style-family="xp"] .{{board.columnHeader}} {
  transition: none;
  min-height: 36px;
  padding: 4px 6px;
  border: 1px solid var(--wecid-xp-edge-light);
}
:root[data-platform="desktop"][data-style-family="xp"] .{{board.columnHeaderDraggable}} { padding-left: 36px; }
:root[data-platform="desktop"][data-style-family="xp"] .{{board.columnHeader}}:not([data-colored="true"]) {
  background: var(--wecid-xp-heading);
  color: var(--wecid-xp-heading-text);
